use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::{fs, io::Read, path::{Path, PathBuf}, time::UNIX_EPOCH};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SourceLocation { pub id: String, pub provider: String, pub label: String, pub path: String, pub session_count: usize, pub status: String, pub last_scanned: Option<String> }

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SessionSummary { pub id: String, pub title: String, pub source: String, pub workspace: Option<String>, pub updated_at: String, pub message_count: usize, pub tool_call_count: usize, pub status: String, pub source_path: String }

fn home() -> PathBuf { std::env::var_os("USERPROFILE").map(PathBuf::from).or_else(|| std::env::var_os("HOME").map(PathBuf::from)).unwrap_or_else(|| PathBuf::from(".")) }
fn now_string() -> String { chrono_like_now() }
fn chrono_like_now() -> String { "local-scan".to_string() }
fn path_string(path: &Path) -> String { path.to_string_lossy().replace('\\', "/") }
fn mtime(path: &Path) -> String { fs::metadata(path).ok().and_then(|m| m.modified().ok()).and_then(|t| t.duration_since(UNIX_EPOCH).ok()).map(|d| d.as_millis().to_string()).unwrap_or_default() }
fn walk(root: &Path, depth: usize, out: &mut Vec<PathBuf>) { if depth > 12 { return; } let Ok(entries)=fs::read_dir(root) else { return; }; for e in entries.flatten() { let p=e.path(); if p.is_dir() { let n=p.file_name().and_then(|x|x.to_str()).unwrap_or_default(); if matches!(n,"node_modules"|".git"|"target"|"dist"|"build"|".cache") { continue; } walk(&p,depth+1,out); } else { out.push(p); } } }
fn read_payload(path: &Path) -> Option<String> { let mut bytes=Vec::new(); fs::File::open(path).ok()?.read_to_end(&mut bytes).ok()?; if path.extension().and_then(|x|x.to_str()).unwrap_or_default().eq_ignore_ascii_case("zst") { zstd::stream::decode_all(bytes.as_slice()).ok().and_then(|b| String::from_utf8(b).ok()) } else { String::from_utf8(bytes).ok() } }
fn records(path: &Path) -> Vec<Value> { let Some(text)=read_payload(path) else { return vec![] }; text.lines().filter_map(|line| serde_json::from_str::<Value>(line).ok()).collect() }
fn text_content(v: &Value) -> String { match v { Value::String(s)=>s.clone(), Value::Array(items)=>items.iter().filter_map(|item| item.get("text").and_then(Value::as_str)).collect::<Vec<_>>().join("\n"), _=>String::new() } }
fn first_user(records: &[Value], kind: &str) -> String { for r in records { let is_user = if kind=="claude" { r.get("type").and_then(Value::as_str)==Some("user") } else if kind=="codex" { r.get("type").and_then(Value::as_str)==Some("response_item") && r.get("payload").and_then(|p|p.get("role")).and_then(Value::as_str)==Some("user") } else if kind=="dsh" { r.get("type").and_then(Value::as_str)==Some("user/message") } else { false }; if !is_user { continue; } let candidate = if kind=="claude" { r.get("message").and_then(|m|m.get("content")).map(text_content).unwrap_or_default() } else if kind=="codex" { r.get("payload").and_then(|p|p.get("content")).map(text_content).unwrap_or_default() } else { r.get("data").and_then(|d|d.get("content")).map(text_content).unwrap_or_default() }; let value=candidate.trim(); if !value.is_empty() && !value.starts_with("<system") { return value.chars().take(80).collect(); } } String::new() }
fn count_tool_calls(records: &[Value]) -> usize { records.iter().filter(|r| { let t=r.get("type").and_then(Value::as_str).unwrap_or_default(); t.contains("tool") || t=="function_call" || t=="response_item" && r.get("payload").and_then(|p|p.get("type")).and_then(Value::as_str).unwrap_or_default().contains("function_call") }).count() }
fn summary_from_json(path: &Path, provider: &str, id: String, title: String, workspace: Option<String>, records: Vec<Value>) -> SessionSummary { SessionSummary { id, title, source: provider.to_string(), workspace, updated_at: mtime(path), message_count: records.len(), tool_call_count: count_tool_calls(&records), status: if records.is_empty(){"warning"}else{"ready"}.to_string(), source_path: path_string(path) } }
fn claude_sessions() -> Vec<SessionSummary> { let root=home().join(".claude/projects"); let mut files=Vec::new(); walk(&root,0,&mut files); files.into_iter().filter(|p|p.extension().and_then(|x|x.to_str())==Some("jsonl")).filter_map(|p| { let rs=records(&p); if rs.is_empty(){return None;} let id=rs.iter().find_map(|r|r.get("sessionId").and_then(Value::as_str)).or_else(||p.file_stem().and_then(|x|x.to_str()))?.to_string(); let title=first_user(&rs,"claude"); let cwd=rs.iter().find_map(|r|r.get("cwd").and_then(Value::as_str)).map(str::to_string); Some(summary_from_json(&p,"claude-code",id,title,cwd,rs)) }).collect() }
fn codex_sessions() -> Vec<SessionSummary> { let mut files=Vec::new(); for root in [home().join(".codex/sessions"),home().join(".codex/archived_sessions")] { walk(&root,0,&mut files); } files.into_iter().filter(|p|p.file_name().and_then(|x|x.to_str()).unwrap_or_default().starts_with("rollout-")).filter_map(|p| { let rs=records(&p); if rs.is_empty(){return None;} let id=p.file_stem().and_then(|x|x.to_str()).unwrap_or_default().trim_start_matches("rollout-").to_string(); let title=first_user(&rs,"codex"); Some(summary_from_json(&p,"codex",id,title,None,rs)) }).collect() }
fn antigravity_sessions() -> Vec<SessionSummary> { let root=home().join(".gemini"); let mut files=Vec::new(); walk(&root,0,&mut files); files.into_iter().filter(|p|p.ends_with("transcript.jsonl") && p.to_string_lossy().contains(".system_generated/logs")).filter_map(|p| { let rs=records(&p); if rs.is_empty(){return None;} let id=p.parent()?.parent()?.parent()?.parent()?.file_name()?.to_str()?.to_string(); let title=rs.iter().find_map(|r| if r.get("type").and_then(Value::as_str)==Some("USER_INPUT"){r.get("content").map(text_content)}else{None}).unwrap_or_default(); Some(summary_from_json(&p,"antigravity",id,title,None,rs)) }).collect() }
fn dsh_sessions() -> Vec<SessionSummary> { let root=home().join(".dsh/sessions"); let mut files=Vec::new(); walk(&root,0,&mut files); files.into_iter().filter(|p|p.file_name().and_then(|x|x.to_str()).map(|n| n.starts_with("session") && (n.ends_with(".jsonl")||n.ends_with(".zstd"))).unwrap_or(false)).filter_map(|p| { let rs=records(&p); let parent=p.parent()?; let id=rs.iter().find_map(|r|r.get("type").and_then(Value::as_str).filter(|t|*t=="session").and_then(|_|r.get("id")).and_then(Value::as_str)).or_else(||parent.file_name().and_then(|x|x.to_str()))?.to_string(); let title=rs.iter().rev().find_map(|r| if r.get("type").and_then(Value::as_str)==Some("session/title"){r.get("data").and_then(|d|d.get("title")).and_then(Value::as_str).map(str::to_string)}else{None}).unwrap_or_else(||first_user(&rs,"dsh")); let workspace=parent.parent().and_then(|p|p.file_name()).and_then(|x|x.to_str()).map(str::to_string); Some(summary_from_json(&p,"dsh",id,title,workspace,rs)) }).collect() }
fn zcode_sessions() -> Vec<SessionSummary> { let path=home().join(".zcode/cli/db/db.sqlite"); let Ok(conn)=rusqlite::Connection::open_with_flags(&path,rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY) else { return vec![] }; let Ok(mut stmt)=conn.prepare("SELECT id, title, directory, time_updated, time_created FROM session WHERE parent_id IS NULL ORDER BY time_updated DESC") else {return vec![]}; let rows=stmt.query_map([],|row| Ok(SessionSummary{id:row.get(0)?,title:row.get::<_,String>(1).unwrap_or_default(),source:"zcode".to_string(),workspace:row.get::<_,Option<String>>(2)?,updated_at:row.get::<_,i64>(3).unwrap_or_else(|_|row.get::<_,i64>(4).unwrap_or_default()).to_string(),message_count:0,tool_call_count:0,status:"ready".to_string(),source_path:path_string(&path)})); rows.map(|iter|iter.filter_map(Result::ok).collect()).unwrap_or_default() }
fn source(id:&str,label:&str,path:PathBuf,count:usize)->SourceLocation { SourceLocation{id:id.to_string(),provider:id.to_string(),label:label.to_string(),path:path_string(&path),session_count:count,status:if count>0{"ready"}else{"unavailable"}.to_string(),last_scanned:Some(now_string())} }
#[tauri::command] pub fn discover_sources()->Vec<SourceLocation>{ let c=claude_sessions(); let x=codex_sessions(); let a=antigravity_sessions(); let d=dsh_sessions(); let z=zcode_sessions(); vec![source("claude-code","Claude Code",home().join(".claude/projects"),c.len()),source("antigravity","Antigravity",home().join(".gemini/antigravity"),a.len()),source("codex","Codex",home().join(".codex/sessions"),x.len()),source("zcode","Zcode",home().join(".zcode/cli/db/db.sqlite"),z.len()),source("dsh","DeepSeek Harness",home().join(".dsh/sessions"),d.len())] }
#[tauri::command] pub fn discover_sessions(provider:String)->Vec<SessionSummary>{ match provider.as_str(){"claude-code"=>claude_sessions(),"antigravity"=>antigravity_sessions(),"codex"=>codex_sessions(),"zcode"=>zcode_sessions(),"dsh"=>dsh_sessions(),_=>vec![]} }

